public static void adjustableChainGearshift(SceneBuilder builder, SceneBuildingUtil util) {
    CreateSceneBuilder scene = new CreateSceneBuilder(builder);
    scene.title("chain_gearshift", "Controlling rotational speed with Chain Gearshifts");
    scene.configureBasePlate(0, 0, 5);
    scene.setSceneOffsetY(-1.0f);
    scene.world().showSection(util.select().layer(0), Direction.UP);
    BlockPos leverPos = util.grid().at(3, 1, 0);
    BlockPos eastDrive = util.grid().at(3, 1, 2);
    BlockPos eastGauge = eastDrive.m_6630_(3);
    BlockPos middleGauge = eastGauge.m_122024_().m_7495_();
    BlockPos westGauge = eastGauge.m_122025_(2).m_6625_(2);
    ElementLink lever = scene.world().showIndependentSection(util.select().fromTo(leverPos, leverPos.m_122019_()), Direction.UP);
    scene.idle(5);
    scene.world().showSection(util.select().fromTo(4, 1, 3, 4, 2, 3), Direction.DOWN);
    scene.idle(10);
    scene.world().showSection(util.select().fromTo(eastDrive, eastDrive.m_122025_(2)).add(util.select().position(eastDrive.m_7494_())), Direction.DOWN);
    scene.idle(10);
    scene.overlay().showText(60).text("Unpowered Chain Gearshifts behave exactly like Chain Drives").attachKeyFrame().placeNearTarget().pointAt(util.vector().blockSurface(eastDrive, Direction.NORTH));
    scene.idle(60);
    scene.world().showSection(util.select().fromTo(eastGauge, eastGauge.m_7495_()), Direction.DOWN);
    scene.idle(5);
    scene.world().showSection(util.select().fromTo(middleGauge, middleGauge.m_7495_()), Direction.DOWN);
    scene.idle(5);
    scene.world().showSection(util.select().position(westGauge), Direction.DOWN);
    scene.idle(5);
    for (BlockPos gauge : new BlockPos[]{eastGauge, middleGauge, westGauge}) {
        scene.idle(5);
        scene.overlay().showText(50).sharedText(gauge == eastGauge ? "rpm16_source" : "rpm16").colored(PonderPalette.MEDIUM).placeNearTarget().pointAt(util.vector().blockSurface(gauge, Direction.NORTH));
    }
    scene.idle(60);
    scene.world().toggleRedstonePower(util.select().fromTo(leverPos, leverPos.m_122020_(2)));
    scene.effects().indicateRedstone(leverPos);
    scene.world().modifyKineticSpeed(util.select().fromTo(westGauge.m_7495_(), middleGauge), f -> Float.valueOf(2.0f * f.floatValue()));
    scene.idle(10);
    AABB bb = new AABB(eastDrive);
    scene.overlay().chaseBoundingBoxOutline(PonderPalette.MEDIUM, (Object)eastDrive, bb, 160);

